/**
 * @file    ota_public_key.h
 * @brief   Ed25519 public key compiled into the bootloader.
 *
 * THIS IS THE DEMO KEY shipped with the reference project. It is generated by
 * `tools/firmware_tool.py keygen` and is not a secret. The matching private
 * key is generated locally under tools/keys/ (git-ignored) and is NEVER
 * committed: CI and release builds supply the private key from a secret.
 *
 * Production procedure:
 *   1. generate a fresh keypair on an offline machine,
 *   2. replace this array with the public half,
 *   3. keep the private half outside the repository (CI secret / signing
 *      service), and rotate it by shipping a bootloader update.
 * See SECURITY.md for the consequences of a leaked signing key.
 */

#ifndef OTA_PUBLIC_KEY_H
#define OTA_PUBLIC_KEY_H

#include <stdint.h>

#define OTA_ED25519_PUBLIC_KEY_BYTES 32u

#define OTA_ED25519_PUBLIC_KEY {                                      \
    0x90, 0xDC, 0x98, 0x9D, 0xA0, 0xBF, 0x18, 0x02,                  \
    0x90, 0xCE, 0x48, 0x53, 0x0E, 0x98, 0x7F, 0xFA,                  \
    0xBE, 0xDA, 0x3B, 0x78, 0x2C, 0x9C, 0x0E, 0x42,                  \
    0xDD, 0x9D, 0x0F, 0x26, 0x5A, 0x05, 0xDD, 0xDC                   \
}

#endif /* OTA_PUBLIC_KEY_H */
